from pathlib import Path
import base64,zlib
PAYLOAD = """"""
html=zlib.decompress(base64.b64decode(PAYLOAD)).decode("utf-8")
for p in [Path("NEW_DARK_RPG/index.html"),Path("android/app/src/main/assets/index.html")]:
    p.write_text(html,encoding="utf-8")
print("Applied canonical v3 game to web and Android asset:",len(html),"bytes")